using TMPro;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// Plain reference holder for the Intro screen PREFAB (Assets/_Project/Prefabs/UI/IntroScreen.prefab,
/// generated by FrontendScreenPrefabs — Tools > MusicGame > UI > Build All UI Prefabs — and edited by hand
/// from then on). IntroScreenController spawns it (UIPrefabLibrarySO.introScreen), only READS these
/// references and drives the fade/skip sequence — it never creates or lays out this UI itself.
/// </summary>
public class IntroScreenView : MonoBehaviour
{
    public GameObject   root;
    public CanvasGroup  canvasGroup;
    [Tooltip("Full-screen invisible button (on Dim): a click/tap anywhere skips the wait.")]
    public Button       skipButton;
    public TextMeshProUGUI titleText;
}
